const $=id=>document.getElementById(id);let apiSourceCredentials={};let externalAiConfigured=false;let evaluatedManualJob=null;let savedResume=null;const api=async(path,options={})=>{const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw Error(data.detail||`Request failed (${response.status})`);return data};
function toast(message){const e=$('toast');e.textContent=message;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2800)}function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function showPage(page){document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===page));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('crumb').textContent={overview:'Chat',matcher:'Fit check',agents:'Search roles',tracker:'Applications',copilot:'Drafts',profile:'Profile',tools:'Tools'}[page]||page;if(page==='agents'){loadSources();loadJobs()}if(page==='tracker')loadApplications();window.scrollTo(0,0)}
function parseList(value){return value.split(',').map(x=>x.trim()).filter(Boolean)}function setVal(id,value){if($(id))$(id).value=value??''}
async function checkSession(){try{await api('/session');$('loginOverlay')?.classList.add('hidden');await initialize()}catch(e){toast(e.message)}}
async function initialize(){try{await loadProfile();syncFreehireQuery();await loadApplications();const s=await api('/status');apiSourceCredentials=s.api_source_credentials||{};externalAiConfigured=!!s.ai_configured;updateSourceGuide();$('systemState').textContent=`Server active · ${s.job_sources} sources · ${s.sponsor_records} sponsorship records${s.email_configured?' · email ready':''}${s.scheduled_search_configured?' · scheduled search ready':''}${s.auto_search_interval_seconds?` · auto search every ${s.auto_search_interval_seconds}s`:''}`;const aiNotice=$('aiNotice');if(!s.ai_configured&&aiNotice)aiNotice.textContent='Local draft mode is available. Configure an AI provider on the server only if you want external resume tailoring.'}catch(e){toast(e.message)}}
function updateHomeResume(resume){savedResume=resume||null;const status=$('homeResumeStatus'),label=$('homeResumeLabel'),button=$('findJobsButton'),workflowStatus=$('oneClickStatus');if(resume){if(status)status.textContent=resume.filename+' · ready';if(label)label.textContent='Replace your resume';if(button)button.disabled=false;if(workflowStatus&&workflowStatus.textContent.startsWith('Upload your resume.'))workflowStatus.textContent='Resume ready. Review the profile if needed, then click Find & prepare jobs.'}else{if(status)status.textContent='No resume uploaded yet';if(label)label.textContent='Choose your resume';if(button)button.disabled=true}}
async function loadProfile(){const {profile:p,resume}=await api('/profile');savedResume=resume||null;setVal('pName',p.name);setVal('pEmail',p.email);setVal('pPhone',p.phone);setVal('pLocation',p.location);setVal('pCompany',p.current_company);setVal('pRole',p.role);setVal('pYears',p.years_experience);setVal('pSkills',(p.skills||[]).join(', '));setVal('pEducation',p.education);setVal('pTargets',(p.target_titles||[]).join(', '));setVal('pLocations',(p.location_preferences||[]).join(', '));setVal('pModes',(p.work_modes||[]).join(', '));setVal('pSalary',p.minimum_salary);setVal('pThreshold',p.match_threshold??50);setVal('pVisa',p.work_authorization||p.sponsorship_preferences);setVal('pSummary',p.summary);$('pAlerts').checked=!!p.email_alerts;$('resumeStatus').textContent=resume?resume.filename+' · uploaded '+new Date(resume.uploaded_at).toLocaleDateString():'No resume uploaded';updateHomeResume(resume);window.dispatchEvent(new CustomEvent('neural-ant:profile-updated',{detail:{profile:p,resume}}));}
async function saveProfile(options={}){try{const p={name:$('pName').value,email:$('pEmail').value,phone:$('pPhone').value,location:$('pLocation').value,current_company:$('pCompany').value,role:$('pRole').value,years_experience:Number($('pYears').value)||null,skills:parseList($('pSkills').value),education:$('pEducation').value,target_titles:parseList($('pTargets').value),location_preferences:parseList($('pLocations').value),work_modes:parseList($('pModes').value),minimum_salary:Number($('pSalary').value)||null,match_threshold:Number($('pThreshold').value)||50,work_authorization:$('pVisa').value,sponsorship_preferences:$('pVisa').value,summary:$('pSummary').value,email_alerts:$('pAlerts').checked};await api('/profile',{method:'PUT',body:JSON.stringify(p)});window.dispatchEvent(new CustomEvent('neural-ant:profile-updated',{detail:{profile:p,resume:savedResume}}));if(!options.silent)toast('Profile saved privately');return p}catch(e){if(!options.silent)toast(e.message);return null}}
async function syncFreehireQuery(savedProfile=null){const input=$('freehireQuery');if(!input)return;if(!input.dataset.bound){input.addEventListener('input',()=>{input.dataset.userEdited='true'});input.dataset.bound='true'}if(input.dataset.userEdited)return;try{let profile=savedProfile;if(!profile)({profile}=await api('/profile'));const titles=(profile.target_titles||[]).slice(0,5).map(title=>String(title).replaceAll('"','').trim()).filter(Boolean);if(titles.length)input.value=titles.map(title=>'title:"'+title+'"').join(' OR ')}catch{}}
async function uploadResume(inputId='resumeFile'){const input=$(inputId);const f=input?.files?.[0];if(!f){toast('Choose a PDF or DOCX resume');return}const homeUpload=inputId==='homeResumeFile';if(homeUpload){$('homeResumeStatus').textContent='Reading your resume and filling the profile…';$('findJobsButton').disabled=true}try{const form=new FormData();form.append('file',f);const result=await api('/resume',{method:'POST',body:form});await loadProfile();const count=(result.updated_profile_fields||[]).length;$('oneClickStatus').textContent='Resume ready. Neural Ant filled '+count+' profile details; review anything missing, then click Find & prepare jobs.';toast('Resume saved. Your profile is ready for the search.')}catch(e){if(homeUpload)$('homeResumeStatus').textContent='Resume upload failed: '+e.message;toast(e.message)}finally{if(input)input.value=''}}
async function importSponsors(){const f=$('sponsorFile').files[0];if(!f){toast('Choose a CSV file');return}try{const form=new FormData();form.append('file',f);const r=await api('/sponsors/import',{method:'POST',body:form});toast(`${r.imported} sponsorship evidence rows imported`)}catch(e){toast(e.message)}}
function updateSourceGuide(){const type=$('sourceType')?.value||'greenhouse';const guides={greenhouse:{label:'Board slug',placeholder:'company-name',name:'Company name',namePlaceholder:'Company name',help:'Use the slug from boards.greenhouse.io/company-name. Only public postings are read.'},lever:{label:'Board slug',placeholder:'company-name',name:'Company name',namePlaceholder:'Company name',help:'Use the slug from jobs.lever.co/company-name. Only public postings are read.'},ashby:{label:'Board name',placeholder:'company-name',name:'Company name',namePlaceholder:'Company name',help:'Use the board name from jobs.ashbyhq.com/company-name. Only public postings are read.'},smartrecruiters:{label:'Company identifier',placeholder:'company-name',name:'Company name',namePlaceholder:'Company name',help:'Use the company identifier from its public SmartRecruiters careers URL.'},adzuna:{label:'Country | keywords | location',placeholder:'us|AI Engineer|Remote',name:'Search label',namePlaceholder:'Adzuna AI jobs',help:'Searches Adzuna public job results. Use a lowercase country code, keywords, and a location separated by vertical bars.'},usajobs:{label:'Keywords | location',placeholder:'AI Engineer|Washington DC',name:'Search label',namePlaceholder:'USAJOBS AI jobs',help:'Searches the USAJOBS public API. Enter keywords and a location separated by a vertical bar.'}};const item=guides[type]||guides.greenhouse;$('sourceSlugLabel').textContent=item.label;$('sourceSlug').placeholder=item.placeholder;$('sourceCompanyLabel').textContent=item.name;$('sourceCompany').placeholder=item.namePlaceholder;$('sourceHelp').textContent=item.help;const credentialNote=$('sourceCredentialNote');if(type==='adzuna'){credentialNote.textContent=apiSourceCredentials.adzuna?'Adzuna credentials are configured.':'Add ADZUNA_APP_ID and ADZUNA_APP_KEY to local .env.local, then restart Neural Ant.'}else if(type==='usajobs'){credentialNote.textContent=apiSourceCredentials.usajobs?'USAJOBS credentials are configured.':'Add USAJOBS_API_KEY and USAJOBS_USER_AGENT to local .env.local, then restart Neural Ant.'}else{credentialNote.textContent='Employer board sources need no API credentials. They are checked on the local search interval.'}}
async function addSource(){try{await api('/sources',{method:'POST',body:JSON.stringify({ats_type:$('sourceType').value,slug:$('sourceSlug').value.trim(),company_name:$('sourceCompany').value.trim()})});$('sourceSlug').value='';$('sourceCompany').value='';await loadSources();toast('Job source added')}catch(e){toast(e.message)}}async function removeSource(id){try{await api(`/sources/${id}`,{method:'DELETE'});await loadSources()}catch(e){toast(e.message)}}async function loadSources(){try{const rows=await api('/sources');$('sourceList').innerHTML=rows.length?rows.map(s=>`<div class="step"><span><strong>${esc(s.company_name)}</strong>${esc(s.ats_type)} / ${esc(s.slug)}</span><button class="btn" onclick="removeSource(${s.id})">Remove</button></div>`).join(''):'<div class="empty">No job sources configured.</div>'}catch(e){}}
async function runSearch(silent=false){const b=document.querySelector('#agents .pagehead .btn');try{if(b){b.disabled=true;b.textContent='Searching…'}const r=await api(`/search/run?days=${Number($('boardSearchDays')?.value||14)}`,{method:'POST'});const errors=Array.isArray(r.source_errors)?r.source_errors.length:0;const health=(r.source_status||[]).map(s=>`${s.company}: ${s.status} (${s.jobs_returned} listings${s.jobs_stale?`, ${s.jobs_stale} older than selected window`:''}${s.invalid_rows?`, ${s.invalid_rows} invalid`:''})`).join(' · ');if($('sourceHealthStatus'))$('sourceHealthStatus').textContent=health||r.message||'No configured sources were checked.';if(!silent)toast(`${r.jobs_seen} postings scanned · ${r.jobs_stale||0} outside date window · ${r.jobs_saved} new · ${r.sources_checked} sources checked · ${r.review_queue_added||0} added to review · ${errors} errors`);if(!silent)await loadJobs();return{ok:true,result:r}}catch(e){if($('sourceHealthStatus'))$('sourceHealthStatus').textContent=`Board search: ${e.message}`;if(!silent)toast(e.message);return{ok:false,error:e.message}}finally{if(b){b.disabled=false;b.textContent='↻ Search now'}}}
async function searchFreehire(silent=false){const button=$('freehireSearchButton');const status=$('freehireStatus');const query=$('freehireQuery').value.trim();const country=$('freehireCountry').value.trim().toUpperCase();if(!/^[A-Z]{2}$/.test(country)){const error='Enter a two-letter country code';status.textContent=error;if(!silent)toast(error);return{ok:false,error}}try{button.disabled=true;button.textContent='Searching…';status.textContent='Searching the public index and scoring results against your saved profile…';const result=await api('/search/freehire',{method:'POST',body:JSON.stringify({query,country,work_mode:$('freehireMode').value,days:Number($('freehireDays').value),limit:Number($('freehireLimit').value)})});status.textContent=result.jobs_returned+' returned from '+Number(result.index_total||0).toLocaleString()+' matching public postings · '+result.jobs_saved+' new · '+result.new_matches+' above your fit threshold · '+result.review_queue_added+' added to review';if(!silent)await loadJobs();if(!silent)toast('Live index search complete');return{ok:true,result}}catch(e){status.textContent=e.message;if(!silent)toast(e.message);return{ok:false,error:e.message}}finally{button.disabled=false;button.textContent='⌕ Search broad index'}}

let oneClickRunning=false;
async function runOneClickWorkflow(){
 if(oneClickRunning)return;
 oneClickRunning=true;
 const buttons=[...document.querySelectorAll('[data-one-click]')];
 buttons.forEach(button=>{button.disabled=true;button.dataset.label=button.textContent;button.textContent='Working…'});
 const status=$('oneClickStatus'),results=$('oneClickResults');
 const setStatus=message=>{if(status)status.textContent=message};
 if(results){results.innerHTML='';results.classList.add('hidden')}
 try{
  if(!savedResume){setStatus('Upload a PDF or DOCX resume to start. The profile fields will fill automatically.');$('homeResumeFile')?.focus({preventScroll:true});return}
  setStatus('Saving your profile and preparing the search…');
  const profileSaved=await saveProfile({silent:true});
  if(!profileSaved)throw Error('Profile could not be saved. Review your profile fields and try again.');
  const {profile}=await api('/profile');
  if(!Array.isArray(profile.target_titles)||!profile.target_titles.length){setStatus('Add at least one target role title in your profile, then start the search.');if(results){results.innerHTML='<button class="btn" type="button" onclick="openWorkflowCommand(\'/setup\')">Review profile preferences</button>';results.classList.remove('hidden')}return}
  await syncFreehireQuery(profile);
  if($('freehireCountry'))$('freehireCountry').value='US';
  if($('freehireMode'))$('freehireMode').value='remote';
  if($('sponsorFilter'))$('sponsorFilter').value='explicit';
  setStatus('Searching employer boards and the remote job index in parallel…');
  const [board,index]=await Promise.all([runSearch(true),searchFreehire(true)]);
  const searchNote='Boards '+(board.ok?'finished':'had an issue')+'; remote index '+(index.ok?'finished':'had an issue')+'.';
  if(!board.ok&&!index.ok){setStatus(searchNote+' No listings were refreshed. Check the job-source settings and try again.');if(results){results.innerHTML='<p>Both search sources failed. Your saved profile and existing application records are unchanged.</p><button class="btn" type="button" onclick="openWorkflowCommand(\'/scrape\')">Review search sources</button>';results.classList.remove('hidden')}return}
  setStatus('Ranking current matches by role fit and sponsorship evidence…');
  await loadJobs();
  const threshold=Math.max(50,Number(profile.match_threshold)||50);
  const rows=await api('/jobs?min_score='+threshold);
  const eligible=rows.filter(job=>job.sponsorship_status==='explicit support; verify role details'&&!/\b(?:h[\s-]?1b|visa)\s+transfers?\b|\btransfers?\s+(?:an?\s+)?h[\s-]?1b\b/i.test(String(job.sponsorship_evidence||''))&&/\b(?:h[\s-]?1b|visa|immigration)\b/i.test(String(job.sponsorship_evidence||''))&&(String(job.work_mode||'')+' '+String(job.location||'')).toLowerCase().includes('remote')&&String(job.url||'').startsWith('https://')).sort((a,b)=>(Number(b.fit_score)||0)-(Number(a.fit_score)||0)).slice(0,5);
  if(!eligible.length){setStatus(searchNote+' No roles met the remote, '+threshold+'% fit, and explicit sponsorship-wording checks. Review other matches if you want to broaden the search.');if(results){results.innerHTML='<p>There are no current roles that meet all three saved filters. Sponsorship wording can be incomplete; use Find roles to inspect listings that need recruiter confirmation.</p><button class="btn" type="button" onclick="openWorkflowCommand(\'/scrape\')">Review all matches</button>';results.classList.remove('hidden')}return}
  setStatus('Preparing review packs for '+eligible.length+' matching role'+(eligible.length===1?'':'s')+'…');
  const [applications,drafts]=await Promise.all([api('/applications'),api('/drafts?summary=true')]);
  const appByJob=new Map(applications.map(item=>[item.job.id,item]));
  const draftByJob=new Map(drafts.map(item=>[item.job_id,item]));
  const ready=[],failures=[];
  for(let i=0;i<eligible.length;i++){
   const job=eligible[i];
   setStatus('Preparing local resume and cover-letter drafts ('+(i+1)+' of '+eligible.length+')…');
   try{
    let application=appByJob.get(job.id);
    if(!application){application=await api('/applications',{method:'POST',body:JSON.stringify({job_id:job.id,notes:'Added by the one-click search and preparation workflow. Review sponsorship and every document before applying.'})});appByJob.set(job.id,application)}
    if(draftByJob.has(job.id)){ready.push({job,application,existing:true});continue}
    await api('/jobs/'+job.id+'/tailor',{method:'POST',body:JSON.stringify({confirmed_resume_use:true,use_external_ai:false})});
    ready.push({job,application,existing:false})
   }catch(error){failures.push({job,message:error.message})}
  }
  await loadApplications();
  const boardCount=Number(board.result?.jobs_seen||0),indexCount=Number(index.result?.jobs_returned||0);
  setStatus(searchNote+' Checked '+boardCount+' employer-board and '+indexCount+' index postings. '+ready.length+' review pack'+(ready.length===1?'':'s')+' ready'+(failures.length?'; '+failures.length+' could not be prepared':'')+'.');
  if(results){
   const list=ready.map(({job,existing})=>'<li><strong>'+esc(job.title)+'</strong> · '+esc(job.company)+' <span>'+Number(job.fit_score||0)+'% fit · '+esc(job.employment_type||'Employment type not stated')+' · '+(existing?'existing draft kept':'local draft prepared')+'</span><span>Sponsorship evidence: '+esc(job.sponsorship_evidence||'Check the posting')+'</span><a href="'+esc(job.url)+'" target="_blank" rel="noopener noreferrer">Open official posting ↗</a></li>').join('');
   const errors=failures.map(({job,message})=>'<li><strong>'+esc(job.title)+'</strong> · '+esc(job.company)+' <span>Could not prepare: '+esc(message)+'</span></li>').join('');
   results.innerHTML='<h3>'+ready.length+' review pack(s) ready</h3><ol>'+list+errors+'</ol><button class="btn" type="button" onclick="showPage(\'tracker\')">Review prepared files</button>';
   results.classList.remove('hidden')
  }
  if(ready.length)toast(ready.length+' application pack(s) are ready for your review.');else toast('Search finished, but no application packs were prepared. See the status above.')
 }catch(error){setStatus('Workflow stopped: '+error.message);toast(error.message)}
 finally{oneClickRunning=false;buttons.forEach(button=>{button.disabled=!savedResume;button.textContent=button.dataset.label||'Find & prepare jobs'})}
}
async function saveProfileAndStartSearch(){return runOneClickWorkflow()}
function ensureManualImportCard(){if($('manualJobLines'))return;const rolesCard=$('cloudJobs')?.closest('.card');if(!rolesCard)return;rolesCard.insertAdjacentHTML('beforebegin',`<div class="card formcard" style="margin-top:15px"><div class="section-title"><h3>Import direct role links</h3><small>user-supplied postings</small></div><p class="helper">Paste one role per line using: URL | employer | title | location | salary | experience | employment type | sponsorship note | role context. Employment type can be Full-time, Contract, Contract-to-hire, C2C, W-2, or 1099. This creates a reviewable role; it does not apply or submit.</p><div class="field"><label>Role lines</label><textarea id="manualJobLines" rows="7" placeholder="https://jobs.example.com/role | Example Corp | Applied AI Engineer | Remote, U.S. | $150K–$180K | 4+ years | C2C / Contract | Sponsorship not stated | Python, agents, RAG, evaluation"></textarea></div><button class="btn primary" onclick="importManualJobs()">＋ Import roles</button><p class="footnote">Verify salary, experience, employment type, sponsorship, and posting status against the official employer page.</p></div>`)}
function renderFitBreakdown(job){const parts=Object.values(job.fit_breakdown||{});if(!parts.length)return '';return `<details class="fit-details"><summary>Why ${Number(job.fit_score)||0}% fit</summary><div class="fit-breakdown">${parts.map(part=>`<div class="fit-row"><span><b>${esc(part.label||'Signal')}</b><small>${esc(part.detail||'')}</small></span><strong>${Number(part.score)||0}/${Number(part.max)||0}</strong></div>`).join('')}</div></details>`}
async function loadJobs(){
 ensureManualImportCard();
 try{
  const profile=await api('/profile');
  const threshold=Math.max(50,Number(profile.profile.match_threshold)||50);
  const [rows,allRows]=await Promise.all([api(`/jobs?min_score=${threshold}`),api('/jobs?min_score=0')]);
  const filter=$('sponsorFilter')?.value||'all';
  const visibleRows=rows.filter(job=>filter==='explicit'?job.sponsorship_status==='explicit support; verify role details':filter==='no_negative'?!['posting says no','conflicting sponsorship wording'].includes(job.sponsorship_status):true);
  const fitCount=allRows.filter(job=>Number(job.fit_score||0)>=threshold).length;
  const importedBelow=allRows.filter(job=>job.source==='Manual'&&Number(job.fit_score||0)<threshold).length;
  $('jobCount').textContent=`${visibleRows.length} shown${filter==='explicit'?' with explicit posting support':filter==='no_negative'?' after hiding explicit negatives':''} · ${fitCount} meet ${threshold}%+ fit${importedBelow?` · ${importedBelow} manual imports below threshold`:''} · ${allRows.length} saved`;
  $('cloudJobs').innerHTML=visibleRows.length?visibleRows.map(job=>`<article class="job"><div class="jobmain"><div class="companymark">${esc(job.company.slice(0,2).toUpperCase())}</div><div><h4>${esc(job.title)} · ${esc(job.company)}</h4><p>${esc(job.location||'Location not stated')} · ${esc(job.work_mode)} · <b>${esc(job.employment_type||'Not stated')}</b> · ${esc(job.salary)}</p><p><b>${job.fit_score}% fit</b> · ${esc(job.sponsorship_status)} — ${esc(job.sponsorship_evidence)}</p>${job.application_deadline?`<p class="footnote">${job.days_until_deadline<0?`⚠ Listed deadline passed ${esc(job.application_deadline)}; verify that the role is still open.`:job.days_until_deadline<=7?`🔥 Deadline ${esc(job.application_deadline)} · ${job.days_until_deadline} day(s) left.`:`Application deadline: ${esc(job.application_deadline)}`}</p>`:''}${job.posted_age_days>30?`<p class="footnote">⚠ Posted ${job.posted_age_days} days ago. Age is a review signal; confirm the official posting is still open.</p>`:''}<p>${esc((job.fit_reasons||[]).join(' · '))}</p>${job.mass_posting_note?`<p class="footnote"><b>Posting pattern:</b> ${esc(job.mass_posting_note)}</p>`:''}${renderFitBreakdown(job)}<a href="${esc(job.url)}" target="_blank" rel="noopener">Open posting / choose apply link ↗</a> ${Object.entries(job.referral_links||{}).map(([kind,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${kind==='recruiters'?'Find recruiters':'Find team peers'} ↗</a>`).join(' ')} <button class="btn primary" onclick="prepareApplication(${job.id})">Prepare for review</button> <button class="btn" onclick="trackJob(${job.id})">Track only</button></div></div></article>`).join(''):'<div class="empty">No saved roles match this filter yet. Search configured sources or broaden the sponsorship evidence filter.</div>';
 }catch(e){$('cloudJobs').innerHTML='<div class="empty">Sign in to load search results.</div>'}
}
function parseManualJobLines(){return $('manualJobLines').value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map((line,index)=>{const parts=line.split('|').map(part=>part.trim());if(parts.length<6)throw Error(`Line ${index+1} needs URL | employer | title | location | salary | experience | employment type | sponsorship note | role context`);const hasEmploymentType=parts.length>=9;return{url:parts[0],company_name:parts[1],title:parts[2],location:parts[3],salary_text:parts[4],experience_text:parts[5],employment_type:hasEmploymentType?parts[6]:'Not stated',sponsorship_note:hasEmploymentType?parts[7]:(parts[6]||''),description:parts.slice(hasEmploymentType?8:7).join(' | ')}})}
async function importManualJobs(){try{const jobs=parseManualJobLines();const r=await api('/jobs/manual',{method:'POST',body:JSON.stringify({jobs})});await loadJobs();toast(`${r.imported} role(s) imported${r.updated?` · ${r.updated} updated`:''} · ${r.review_queue_added||0} added to review`)}catch(e){toast(e.message)}}
setInterval(()=>{if(document.visibilityState==='visible'&&document.getElementById('agents')?.classList.contains('active'))loadJobs()},60000);
async function prepareApplication(id){try{await api('/applications',{method:'POST',body:JSON.stringify({job_id:id})});await loadApplications();await tailorJob(id)}catch(e){toast(e.message)}}async function trackJob(id){try{await api('/applications',{method:'POST',body:JSON.stringify({job_id:id})});toast('Added to your application tracker');await loadApplications()}catch(e){toast(e.message)}}async function tailorJob(id){
 const useAI=externalAiConfigured&&confirm('Use the configured external AI provider for this application pack? It will receive your resume text, job posting, and selected skills/experience/education facts to draft a resume and cover letter, run a separate review, and revise both. Neural Ant removes common phone, email, URL, street-address, and work-authorization details first, but automatic redaction may miss unusual formats. Choose Cancel for local, fact-grounded drafts.');
 if(!externalAiConfigured)toast('No external AI provider is configured; using local draft mode.');
 try{
  const jobs=await api('/jobs');
  const job=jobs.find(item=>item.id===id);
  if(job){setVal('copilotTitle',job.title);setVal('copilotCompany',job.company);setVal('copilotContext',job.description||'');}
  $('taskType').value='resume';
  const result=await api(`/jobs/${id}/tailor`,{method:'POST',body:JSON.stringify({confirmed_resume_use:true,use_external_ai:useAI})});
  renderDraft(result.content);$('coverLetterResult').textContent=result.cover_letter?`COVER LETTER DRAFT\n\n${result.cover_letter}`:'';$('coverLetterResult').classList.toggle('hidden',!result.cover_letter);$('applicationReviewResult').textContent=`REVIEW NOTES\n\n${result.review_notes||'No review notes returned.'}`;$('applicationReviewResult').classList.remove('hidden');showPage('copilot');toast('Resume and cover-letter pack saved. Review every claim before using it.')
 }catch(e){toast(e.message)}
}
async function loadApplications(){
 try{
  const items=await api('/applications');
  $('statApps').textContent=items.length;
  $('statAnalyzed').textContent=(await api('/jobs')).length;
  $('statFit').textContent=items.length?`${Math.max(...items.map(x=>x.job.fit_score))}%`:'—';
  const stages=['Shortlist','Applied','Interview','Decision','Archived'];
  const today=new Date().toISOString().slice(0,10);
  const due=items.filter(x=>x.follow_up_on&&x.follow_up_on<=today&&x.stage!=='Archived'&&!x.outcome).length;
  if($('statFollow'))$('statFollow').textContent=due;
  const pipelineNote=$('statPipelineNote');
  if(pipelineNote)pipelineNote.textContent=stages.map(stage=>`${stage} ${items.filter(x=>x.stage===stage).length}`).join(' · ')+` · Follow-ups due ${due}`;
  $('kanban').innerHTML=stages.map(stage=>`<div class="column"><div class="colhead">${stage}<span>${items.filter(x=>x.stage===stage).length}</span></div>${items.filter(x=>x.stage===stage).map(x=>`<div class="jobcard"><b>${esc(x.job.title)}</b><span>${esc(x.job.company)} · ${esc(x.job.employment_type||'Not stated')} · Role fit ${x.job.fit_score}%</span><br><a href="${esc(x.job.url)}" target="_blank" rel="noopener">Posting ↗</a><div class="tracker-actions"><button class="btn" onclick="downloadResume(${x.id})">Download tailored resume</button><button class="btn" onclick="downloadCoverLetter(${x.id})">Download cover letter</button><select aria-label="Application stage" onchange="setStage(${x.id},this.value)">${stages.map(value=>`<option ${value===x.stage?'selected':''}>${value}</option>`).join('')}</select></div><label class="tracker-label" for="follow-${x.id}">Follow-up date</label><input class="tracker-input" id="follow-${x.id}" type="date" value="${esc(x.follow_up_on||'')}"><label class="tracker-label" for="outcome-${x.id}">Outcome</label><select class="tracker-input" id="outcome-${x.id}"><option value="" ${!x.outcome?'selected':''}>Open / not decided</option>${['Hired','Rejected','No response','Offer declined','Withdrawn'].map(value=>`<option value="${value}" ${value===x.outcome?'selected':''}>${value}</option>`).join('')}</select><label class="tracker-label" for="notes-${x.id}">Notes and feedback</label><textarea class="tracker-notes" id="notes-${x.id}" rows="2">${esc(x.notes||'')}</textarea><div class="tracker-actions"><button class="btn" onclick="saveApplicationDetails(${x.id})">Save details</button><button class="btn lite" onclick="draftFollowup(${x.id})" ${x.followup_draft_count>=2?'disabled title="Two follow-up drafts already saved"':''}>Draft follow-up (${x.followup_draft_count||0}/2)</button>${x.archive_snapshot?`<button class="btn lite" onclick="downloadArchive(${x.id})">Download archive snapshot</button>`:''}</div>${x.followup_draft_count?`<details class="saved-followups"><summary>Saved follow-up drafts (${x.followup_draft_count}/2)</summary>${(x.followup_drafts||[]).map((draft,index)=>`<details><summary>Draft ${index+1} · ${esc(String(draft.created_at||'').slice(0,10))}</summary><pre>${esc(draft.content||'')}</pre></details>`).join('')}</details>`:''}<details class="interview-panel"><summary>Interview prep${x.interview_prep?' · saved':''}</summary><div class="two"><div class="field"><label>Stage</label><select id="interview-stage-${x.id}"><option>Phone screen</option><option>Technical round</option><option>Hiring manager</option><option>Case or system design</option><option>Final round</option></select></div><div class="field"><label>Date (optional)</label><input id="interview-date-${x.id}" type="datetime-local"></div></div><div class="two"><div class="field"><label>Format</label><select id="interview-format-${x.id}"><option>Not stated</option><option>Phone</option><option>Video</option><option>On-site</option><option>Case exercise</option></select></div><div class="field"><label>Interviewer (optional)</label><input id="interview-person-${x.id}" placeholder="Name or role"></div></div><button class="btn" onclick="prepareInterview(${x.id})">Build / refresh interview pack</button><pre class="interview-pack ${x.interview_prep?'':'hidden'}" id="interview-pack-${x.id}">${esc(x.interview_prep||'')}</pre></details></div>`).join('')||'<div class="empty">No roles here yet</div>'}</div>`).join('');
 }catch(e){toast(e.message)}
}
async function downloadResume(id){try{const response=await fetch(`/api/applications/${id}/resume`,{credentials:'same-origin'});if(!response.ok){let detail='Resume download failed';try{detail=(await response.json()).detail||detail}catch{}throw Error(detail)}const blob=await response.blob();const disposition=response.headers.get('content-disposition')||'';const match=disposition.match(/filename="([^"]+)"/i);const filename=match?.[1]||'tailored-resume.docx';const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast(`Downloaded ${filename}. Review it before uploading.`)}catch(e){toast(e.message)}}
async function downloadCoverLetter(id){try{const response=await fetch(`/api/applications/${id}/cover-letter`,{credentials:'same-origin'});if(!response.ok){let detail='Cover letter download failed';try{detail=(await response.json()).detail||detail}catch{}throw Error(detail)}const blob=await response.blob();const disposition=response.headers.get('content-disposition')||'';const match=disposition.match(/filename="([^"]+)"/i);const filename=match?.[1]||'cover-letter.docx';const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast(`Downloaded ${filename}. Review it before using.`)}catch(e){toast(e.message)}}
async function downloadArchive(id){try{const response=await fetch(`/api/applications/${id}/archive`,{credentials:'same-origin'});if(!response.ok){let detail='Archive download failed';try{detail=(await response.json()).detail||detail}catch{}throw Error(detail)}const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`neural-ant-archive-${id}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}catch(e){toast(e.message)}}
async function prepareInterview(id){try{const result=await api(`/applications/${id}/interview-prep`,{method:'POST',body:JSON.stringify({stage:$(`interview-stage-${id}`).value,interview_date:$(`interview-date-${id}`).value,format:$(`interview-format-${id}`).value,interviewer:$(`interview-person-${id}`).value.trim()})});const box=$(`interview-pack-${id}`);box.textContent=result.pack;box.classList.remove('hidden');toast('Interview pack saved to this application')}catch(e){toast(e.message)}}
let staleRoleDismissals=new Set();
async function loadStaleApplications(){try{const result=await api('/applications/stale?days=60');const box=$('staleApplications');box.classList.remove('hidden');const items=(result.applications||[]).filter(item=>!staleRoleDismissals.has(item.id));box.innerHTML=`<strong>${items.length} open role(s) have had no tracker update for at least 60 days.</strong><p>Review each one. Neural Ant will not close these automatically.</p>`+(items.length?items.map(item=>`<div class="stale-row"><span><b>${esc(item.job.title)}</b> · ${esc(item.job.company)} · ${item.age_days} days since update · ${esc(item.stage)}</span><span class="tracker-actions"><button class="btn" onclick="archiveStaleApplication(${item.id})">Archive as no response</button><button class="btn lite" onclick="dismissStaleApplication(${item.id})">Keep open</button></span></div>`).join(''):'<div class="empty">No stale roles remain in this review.</div>');}catch(e){toast(e.message)}}
function dismissStaleApplication(id){staleRoleDismissals.add(id);loadStaleApplications()}
async function archiveStaleApplication(id){if(!confirm('Archive this role and record “No response”? This saves a local snapshot of the posting and latest prepared documents.'))return;try{await api(`/applications/${id}`,{method:'PATCH',body:JSON.stringify({stage:'Archived',outcome:'No response'})});staleRoleDismissals.delete(id);await loadApplications();await loadStaleApplications();toast('Role archived with a local snapshot')}catch(e){toast(e.message)}}
async function setStage(id,stage){
 try{await api(`/applications/${id}`,{method:'PATCH',body:JSON.stringify({stage})});await loadApplications()}
 catch(e){toast(e.message)}
}
async function saveApplicationDetails(id){
 try{
  await api(`/applications/${id}`,{method:'PATCH',body:JSON.stringify({follow_up_on:$(`follow-${id}`).value,outcome:$(`outcome-${id}`).value,notes:$(`notes-${id}`).value})});
  toast('Application notes and follow-up saved');await loadApplications()
 }catch(e){toast(e.message)}
}
async function draftFollowup(id){
 try{
  const application=(await api('/applications')).find(item=>item.id===id);
  if(!application)throw Error('Application not found');
  const result=await api(`/applications/${id}/follow-up-draft`,{method:'POST',body:JSON.stringify({})});
  setVal('copilotTitle',application.job.title);setVal('copilotCompany',application.job.company);setVal('copilotContext',`Application stage: ${application.stage}. Notes: ${application.notes||'No notes saved.'}`);
  $('taskType').value='followup';updateCopilotFields();renderDraft(result.draft.content);showPage('copilot');await loadApplications();toast(`Follow-up draft saved (${result.count}/${result.limit}). Review before sending.`)
 }catch(e){toast(e.message)}
}
function updateCopilotFields(){
 const isInterview=$('taskType')?.value==='interview';
 $('interviewStageField')?.classList.toggle('hidden',!isInterview)
}
function renderDraft(text){
 $('draftResult').textContent=text;$('draftResult').classList.remove('hidden');
 $('draftReviewResult').textContent='';$('draftReviewResult').classList.add('hidden');
 $('coverLetterResult').textContent='';$('coverLetterResult').classList.add('hidden');
 $('applicationReviewResult').textContent='';$('applicationReviewResult').classList.add('hidden');
 $('reviewDraftAction').classList.remove('hidden')
}
async function reviewDraft(){
 const content=$('draftResult').textContent.trim();if(!content){toast('Create a draft first');return}
 try{
  const result=await api('/drafts/review',{method:'POST',body:JSON.stringify({content})});
  const lines=[result.status,...(result.unverified_numbers.length?[`Numbers not found in resume: ${result.unverified_numbers.join(', ')}`]:[]),...(result.technologies_not_found_in_source.length?[`Technologies not found in resume: ${result.technologies_not_found_in_source.join(', ')}`]:[]),result.note];
  $('draftReviewResult').textContent=lines.join('\n\n');$('draftReviewResult').classList.remove('hidden')
 }catch(e){toast(e.message)}
}
function currentManualJob(){return{url:$('jobUrl').value.trim(),title:$('jobTitle').value.trim(),company_name:$('jobCompany').value.trim(),location:$('jobLocation').value.trim(),work_mode:$('jobWorkMode').value,employment_type:$('jobEmploymentType').value,salary_text:$('jobSalary').value.trim()||'Not stated',description:$('jobDescription').value.trim()}}
function analyzeJob(){
 const job=currentManualJob(),{url,...payload}=job;
 if(!job.title||!job.description){toast('Add a job title and description first');return}
 api('/jobs/evaluate',{method:'POST',body:JSON.stringify(payload)}).then(result=>{
  evaluatedManualJob=JSON.stringify(job);
  const rows=Object.values(result.fit_breakdown||{}).map(item=>`<div class="fit-row"><b>${esc(item.label)} <span>${item.score}/${item.max}</span></b><small>${esc(item.detail)}</small></div>`).join('');
  const matched=result.matched_profile_skills.length?result.matched_profile_skills.map(esc).join(', '):'No saved profile skills found in the posting.';
  const gaps=result.profile_skills_not_found.length?result.profile_skills_not_found.map(esc).join(', '):'No unmentioned saved skills.';
  $('matchResult').innerHTML=`<div class="fit-summary"><strong>${result.fit_score}% profile fit</strong><span>${esc(result.recommendation)}</span></div><p>${esc(result.review_note)}</p><div class="fit-grid">${rows}</div><p><b>Saved skills mentioned:</b> ${matched}</p><p><b>Saved skills not mentioned:</b> ${gaps}</p><p><b>Sponsorship signal:</b> ${esc(result.sponsorship_status)}. ${esc(result.sponsorship_evidence)}</p>`;
  $('matchResult').classList.remove('hidden');$('saveEvaluatedJob').classList.remove('hidden');$('saveEvaluatedJob').disabled=false;$('saveEvaluatedJob').textContent='＋ Save role to application tracker';toast('Role fit breakdown ready')
 }).catch(e=>toast(e.message))
}
async function saveEvaluatedJob(){
 const job=currentManualJob();
 if(!evaluatedManualJob||JSON.stringify(job)!==evaluatedManualJob){toast('The posting changed. Analyze it again before saving.');return}
 if(!job.url||!job.company_name){toast('Add the official HTTPS job link and company name first.');return}
 const button=$('saveEvaluatedJob');button.disabled=true;button.textContent='Saving…';
 try{
  const imported=await api('/jobs/manual',{method:'POST',body:JSON.stringify({jobs:[job]})});
  const saved=imported.jobs?.[0];if(!saved?.id)throw Error('The role was not saved. Check its HTTPS link and try again.');
  await api('/applications',{method:'POST',body:JSON.stringify({job_id:saved.id,notes:'Saved after reviewing the profile fit breakdown.'})});
  button.textContent='✓ Saved to application tracker';toast('Role saved to your tracker for review');await loadApplications()
 }catch(e){button.disabled=false;button.textContent='＋ Save role to application tracker';toast(e.message)}
}
function makeDraft(){
 const context=$('copilotContext').value.trim();if(!context){toast('Add job details first');return}
 const kind=$('taskType').value,role=$('pRole').value.trim(),skills=parseList($('pSkills').value),name=$('pName').value.trim()||'[Your name]';
 const title=$('copilotTitle').value.trim()||'[Role title]',company=$('copilotCompany').value.trim()||'[Company]';
 const summary=$('pSummary')?.value.trim()||'';
 const jobText=context.toLowerCase();
 const matched=skills.filter(skill=>jobText.includes(skill.toLowerCase()));
 const termPool=['Python','TypeScript','JavaScript','AWS','Azure','Terraform','LLM','RAG','BERT','SageMaker','LangGraph','Temporal','PostgreSQL','MongoDB','Neo4j','React','Kubernetes','Docker','Kafka','Spark','RabbitMQ','FastAPI','PyTorch','FHIR','SQS','DynamoDB','MCP','OpenTelemetry'];
 const roleTerms=termPool.filter(term=>jobText.includes(term.toLowerCase()));
 const notListed=roleTerms.filter(term=>!skills.some(skill=>{const normalized=skill.toLowerCase(),candidate=term.toLowerCase();return normalized===candidate||normalized.includes(candidate)||(candidate.length>=4&&candidate.includes(normalized))}));
 let text='';
 if(kind==='cover'){
  const evidence=summary||`My background as ${role||'an AI engineer'} includes ${matched.length?matched.slice(0,6).join(', '):skills.slice(0,6).join(', ')}.`;
  text=`COVER LETTER DRAFT\n\nDear Hiring Manager,\n\nI am applying for the ${title} role at ${company}. The role's focus on ${matched.slice(0,4).join(', ')||'reliable AI and cloud systems'} stood out to me.\n\n${evidence}\n\nI would bring hands-on experience with ${matched.slice(0,6).join(', ')||skills.slice(0,6).join(', ')||'the skills in my resume'}, along with a practical focus on clear results, reliable services, and careful handling of data.\n\nThank you for considering my application. I would welcome the chance to discuss how my experience fits the team's needs.\n\nSincerely,\n${name}\n\nReview the claims and replace any bracketed details before using.`
 }else if(kind==='interview'){
  const stage=$('interviewStage').value;
  const questions=stage==='Phone screen'?['What kind of AI work are you looking for next?','Walk me through one production system you owned.','What are your location and availability preferences?']:stage==='Technical round'||stage==='Case or system design'?['How would you design a reliable workflow around an AI step?','How do you test quality and handle retries or partial failures?','How would you protect private customer data?']:stage==='Hiring manager'?['How do you take a feature from an unclear problem to production?','Tell me about a production issue you diagnosed and fixed.','How do you work through a technical disagreement?']:['Why this role and team?','Which result from your experience best shows your impact?','What questions or concerns should we address before a decision?'];
  text=`INTERVIEW PREP | ${stage}\n${title} at ${company}\n\nLIKELY QUESTIONS\n${questions.map((q,i)=>`${i+1}. ${q}`).join('\n')}\n\nEVIDENCE TO PREPARE\n${summary||'Use examples from your verified resume.'}\nProfile skills mentioned in the posting: ${matched.join(', ')||'none found in the saved skills list'}\n\nTERMS TO REVIEW\n${notListed.length?notListed.join(', ')+' appear in the posting but are not in your saved skills list. Treat this as a prompt to check your experience, not proof that you lack the skill. Prepare an honest example or explain what you have not used yet.':'No tracked skill gaps found in this quick comparison.'}\n\nSTAR NOTES\nSituation: What was happening?\nTask: What were you responsible for?\nAction: What did you do personally?\nResult: What changed, and what evidence supports it?\n\nQUESTIONS TO ASK\n- How is the team measuring quality and reliability for this work?\n- What would success look like in the first six months?\n- Which parts of the workflow are already in production?\n\nUse this pack before the interview. Follow the employer's rules during the interview; do not use AI assistance if the employer prohibits it.`
 }else if(kind==='upskill'){
  text=`SKILL-GAP LEARNING PLAN | ${title} at ${company}\n\nThese terms appear in the posting but are not listed in your saved profile. This is a checklist to review, not a claim that you lack them.\n\n${notListed.length?notListed.map((term,i)=>`${i+1}. ${term}\n   - Check whether you have used it and update your profile only with confirmed experience.\n   - If new to it, read the official documentation and build a small practice example.\n   - Write down what you tested, what failed, and how you measured the result.`).join('\n\n'):'No terms from the supported technology list were missing from your saved skills.'}\n\nProfile skills that also appear in the posting: ${matched.join(', ')||'none detected'}\n\nThis is a starter plan. Choose the gaps most central to the role; do not add a skill to your resume until you can support it with real experience.`
 }else if(kind==='followup'){
  const stageLine=context.split('\n')[0]||'Application in progress';
  text=`FOLLOW-UP EMAIL DRAFT | ${title} at ${company}\n\nSubject: Following up on my ${title} application\n\nHello [Recruiter or Hiring Manager],\n\nI am following up on my application for the ${title} role at ${company}. I remain interested in the opportunity and would appreciate any update you can share about next steps.\n\n${stageLine}\n\nThank you,\n${name}\n\nDraft only. Confirm the recipient, timing, and details before sending. Neural Ant does not send this message.`
 }else if(kind==='outreach'){
  text=`RECRUITER MESSAGE DRAFT | ${title} at ${company}\n\nHello [Name],\n\nI am interested in the ${title} role at ${company}. My background includes ${matched.slice(0,5).join(', ')||skills.slice(0,5).join(', ')||'the experience in my resume'}. Would you be open to sharing what the team is prioritizing for this position?\n\nThank you,\n${name}\n\nDraft only. Verify names and role details before sending.`
 }else{
  text=`RESUME TAILORING CHECKLIST | ${title} at ${company}\n\nPROFILE SKILLS MENTIONED IN THE POSTING\n${matched.join(', ')||'No exact saved-skill matches found.'}\n\nTERMS TO REVIEW AGAINST YOUR EXPERIENCE\n${notListed.join(', ')||'No supported technology terms were unlisted.'}\n\nSOURCE PROFILE\n${summary||'Add verified accomplishments to your profile summary.'}\n\nUse only achievements, dates, tools, and metrics from your saved resume. Reorder and clarify existing facts; do not add skills or results you cannot verify.`
 }
 renderDraft(text)
}

function exportData(){api('/profile').then(async p=>{const jobs=await api('/jobs');const apps=await api('/applications');const blob=new Blob([JSON.stringify({profile:p,jobs,applications:apps},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='neural-ant-backup.json';a.click();URL.revokeObjectURL(a.href)}).catch(e=>toast(e.message))}async function clearData(){if(!confirm('Delete your stored resume? This cannot be undone.'))return;try{await api('/resume',{method:'DELETE'});toast('Stored resume deleted');await loadProfile()}catch(e){toast(e.message)}}
function ensureApplicationProfileCard(){if($('applicationProfileCard'))return;const base=$('profile')?.querySelector('.formcard');if(!base)return;base.insertAdjacentHTML('afterend','<div class="card formcard" id="applicationProfileCard" style="margin-top:15px"><div class="section-title"><h3>Reusable application profile</h3><small>user-edited fields</small></div><p class="helper">When you upload a resume, Neural Ant fills only fields supported by text in that resume. If a detail is not in the resume, it stays blank. Review and edit these fields before use. Never store passwords, SSNs, signatures, or employer-account credentials here. Legal, work-authorization, sponsorship, demographic, and job-specific questions stay manual.</p><div class="two"><div class="field"><label>Preferred name</label><input id="pPreferredName" placeholder="Optional"></div><div class="field"><label>Country</label><input id="pCountry" placeholder="Only if in resume"></div></div><div class="two"><div class="field"><label>Address line 1</label><input id="pAddress1"></div><div class="field"><label>Address line 2</label><input id="pAddress2"></div></div><div class="two"><div class="field"><label>City</label><input id="pCity"></div><div class="field"><label>State / province</label><input id="pState"></div></div><div class="two"><div class="field"><label>Postal code</label><input id="pPostal"></div><div class="field"><label>Availability date</label><input id="pAvailability" placeholder="YYYY-MM-DD or discuss"></div></div><div class="two"><div class="field"><label>LinkedIn URL</label><input id="pLinkedin" type="url" placeholder="https://linkedin.com/in/..."></div><div class="field"><label>GitHub URL</label><input id="pGithub" type="url" placeholder="https://github.com/..."></div></div><div class="two"><div class="field"><label>Portfolio URL</label><input id="pPortfolio" type="url"></div><div class="field"><label>Other website URL</label><input id="pWebsite" type="url"></div></div><div class="field"><label>Employment history</label><textarea id="pEmploymentHistory" rows="5" placeholder="Employer | title | start YYYY-MM | end YYYY-MM/current | location | verified highlights"></textarea><p class="footnote">One role per line. Use verified facts only.</p></div><div class="field"><label>Education history</label><textarea id="pEducationHistory" rows="4" placeholder="School | degree | field of study | start YYYY-MM | end YYYY-MM"></textarea></div><div class="two"><div class="field"><label>Certifications / licenses</label><textarea id="pCertifications" rows="3" placeholder="Name | issuer | expiry or N/A"></textarea></div><div class="field"><label>Languages</label><textarea id="pLanguages" rows="3" placeholder="Language | proficiency"></textarea></div></div><div class="two"><div class="field"><label>Notice period</label><input id="pNotice" placeholder="e.g. 2 weeks"></div><div class="field"><label>Employment types</label><input id="pEmploymentTypes" placeholder="Full-time, Contract, Contract-to-hire, C2C, W-2, 1099"></div></div><div class="two"><div class="field"><label>Relocation preference</label><input id="pRelocation" placeholder="Open, not open, or details"></div><div class="field"><label>Travel preference</label><input id="pTravel" placeholder="e.g. Up to 10%"></div></div><button class="btn primary" onclick="saveProfile()">Save application profile</button></div>')}
function recordLines(rows,keys){return(Array.isArray(rows)?rows:[]).map(row=>keys.map(key=>String(row?.[key]??'')).join(' | ')).join('\n')}function parseRecordLines(value,keys){return String(value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const parts=line.split('|').map(part=>part.trim());return Object.fromEntries(keys.map((key,index)=>[key,parts[index]||'']))})}
function readVal(id){return $(id)?.value.trim()||''}function applicationProfilePayload(){return{preferred_name:readVal('pPreferredName'),address_line1:readVal('pAddress1'),address_line2:readVal('pAddress2'),city:readVal('pCity'),state:readVal('pState'),postal_code:readVal('pPostal'),country:readVal('pCountry'),linkedin_url:readVal('pLinkedin'),github_url:readVal('pGithub'),portfolio_url:readVal('pPortfolio'),website_url:readVal('pWebsite'),availability_date:readVal('pAvailability'),notice_period:readVal('pNotice'),employment_type_preferences:parseList(readVal('pEmploymentTypes')),relocation_preference:readVal('pRelocation'),travel_preference:readVal('pTravel'),employment_history:parseRecordLines(readVal('pEmploymentHistory'),['company','title','start_date','end_date','location','highlights']),education_history:parseRecordLines(readVal('pEducationHistory'),['school','degree','field','start_date','end_date']),certifications:parseRecordLines(readVal('pCertifications'),['name','issuer','expiry']),languages:parseRecordLines(readVal('pLanguages'),['language','proficiency'])}}
function syncApplicationProfile(p){ensureApplicationProfileCard();setVal('pPreferredName',p.preferred_name);setVal('pAddress1',p.address_line1);setVal('pAddress2',p.address_line2);setVal('pCity',p.city);setVal('pState',p.state);setVal('pPostal',p.postal_code);setVal('pCountry',p.country);setVal('pLinkedin',p.linkedin_url);setVal('pGithub',p.github_url);setVal('pPortfolio',p.portfolio_url);setVal('pWebsite',p.website_url);setVal('pAvailability',p.availability_date);setVal('pNotice',p.notice_period);setVal('pEmploymentTypes',(p.employment_type_preferences||[]).join(', '));setVal('pRelocation',p.relocation_preference);setVal('pTravel',p.travel_preference);setVal('pEmploymentHistory',recordLines(p.employment_history,['company','title','start_date','end_date','location','highlights']));setVal('pEducationHistory',recordLines(p.education_history,['school','degree','field','start_date','end_date']));setVal('pCertifications',recordLines(p.certifications,['name','issuer','expiry']));setVal('pLanguages',recordLines(p.languages,['language','proficiency']))}
const baseLoadProfile=loadProfile;loadProfile=async function(){ensureApplicationProfileCard();await baseLoadProfile();const {profile:p}=await api('/profile');syncApplicationProfile(p)}
window.saveProfile=async function(options={}){const silent=options?.silent===true;try{const p={name:readVal('pName'),email:readVal('pEmail'),phone:readVal('pPhone'),location:readVal('pLocation'),current_company:readVal('pCompany'),role:readVal('pRole'),years_experience:Number(readVal('pYears'))||null,skills:parseList(readVal('pSkills')),education:readVal('pEducation'),target_titles:parseList(readVal('pTargets')),location_preferences:parseList(readVal('pLocations')),work_modes:parseList(readVal('pModes')),minimum_salary:Number(readVal('pSalary'))||null,match_threshold:Number(readVal('pThreshold'))||50,work_authorization:readVal('pVisa'),sponsorship_preferences:readVal('pVisa'),summary:readVal('pSummary'),email_alerts:$('pAlerts').checked,...applicationProfilePayload()};await api('/profile',{method:'PUT',body:JSON.stringify(p)});await syncFreehireQuery();if(!silent)toast('Profile and reusable application fields saved privately');return true}catch(e){toast(e.message);return false}}
const baseLoadJobs=loadJobs;
loadJobs=async function(){await baseLoadJobs();const counter=$('jobCount');if(counter&&!counter.textContent.includes('refreshed'))counter.textContent+=` · refreshed ${new Date().toLocaleTimeString()}`};
const baseInitialize=initialize;
initialize=async function(){await baseInitialize();await loadJobs()};
const installAppButton=document.createElement('button');
installAppButton.id='installApp';installAppButton.type='button';installAppButton.className='btn install-app';installAppButton.textContent='Install';installAppButton.setAttribute('aria-label','Install Neural Ant on this device');installAppButton.hidden=true;
document.querySelector('.topbar .profile')?.prepend(installAppButton);
let installPromptEvent=null;
const standaloneMode=window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;
const iosDevice=/iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
if(!standaloneMode&&iosDevice)installAppButton.hidden=false;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPromptEvent=event;installAppButton.hidden=false});
installAppButton.addEventListener('click',async()=>{if(installPromptEvent){installPromptEvent.prompt();const choice=await installPromptEvent.userChoice;installPromptEvent=null;if(choice.outcome==='accepted')installAppButton.hidden=true;return}if(iosDevice){toast('In Safari, tap Share, then Add to Home Screen.')}else{toast('Open your browser menu and choose Install app or Add to Home Screen.')}});
window.addEventListener('appinstalled',()=>{installAppButton.hidden=true;installPromptEvent=null});
async function downloadApplicationReport(){try{const response=await fetch('/api/reports/applications.html',{credentials:'same-origin'});if(!response.ok){let detail='Report download failed';try{detail=(await response.json()).detail||detail}catch{}throw Error(detail)}const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='neural-ant-application-report.html';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Downloaded the offline application report.')}catch(e){toast(e.message)}}

let emailProposalForApproval=null;
const baseShowPageForTools=showPage;
showPage=function(page){baseShowPageForTools(page);if(page==='tools')loadWorkspaceTools()};
async function loadWorkspaceTools(){try{const p=await api('/profile');if(!$('expandUrl').value)$('expandUrl').value=p.profile.github_url||p.profile.portfolio_url||p.profile.website_url||'';await Promise.all([loadSkillSuggestions(),loadTemplates()])}catch(e){toast(e.message)}}
function renderSkillSuggestions(items){const box=$('skillSuggestions');if(!box)return;box.innerHTML=items.length?items.map(item=>`<div class="step" style="align-items:flex-start"><input class="skill-suggestion-check" type="checkbox" value="${esc(item.id)}" style="margin-top:5px"><span><strong>${esc(item.skill)}</strong>${(item.sources||[]).map(source=>`<small>${esc(source.label)} · <a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">view source</a><br>${esc(source.excerpt)}</small>`).join('')}</span></div>`).join('')+'<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" onclick="decideSkillSuggestions(true)">Add checked skills</button><button class="btn" onclick="decideSkillSuggestions(false)">Dismiss checked</button></div>':'<div class="empty">No pending evidence. Scan a source excerpt to suggest skills.</div>'}
async function loadSkillSuggestions(){try{const result=await api('/profile/expansion');renderSkillSuggestions(result.suggestions||[])}catch(e){if($('skillSuggestions'))$('skillSuggestions').textContent=e.message}}
async function expandProfileSource(){const label=$('expandLabel').value.trim();const url=$('expandUrl').value.trim();const text=$('expandText').value.trim();if(!label||!url||!text){toast('Add a source label, public HTTPS URL, and copied text');return}try{const result=await api('/profile/expand',{method:'POST',body:JSON.stringify({sources:[{label,url,text}]})});await loadSkillSuggestions();toast(`${result.suggestions.length} skill suggestion(s) found. Review evidence before adding.`)}catch(e){toast(e.message)}}
async function decideSkillSuggestions(approve){const ids=[...document.querySelectorAll('.skill-suggestion-check:checked')].map(el=>el.value);if(!ids.length){toast('Check at least one suggestion');return}try{const result=await api('/profile/expand/decide',{method:'POST',body:JSON.stringify(approve?{approve_ids:ids}:{dismiss_ids:ids})});await loadSkillSuggestions();if(approve){await loadProfile();await loadJobs()}toast(approve?`${result.approved} verified skill(s) added to your profile`:`${result.dismissed} suggestion(s) dismissed`)}catch(e){toast(e.message)}}
async function loadTemplates(){try{const rows=await api('/templates');$('templateList').innerHTML=rows.length?rows.map(item=>`<div class="step"><span><strong>${esc(item.name)}${item.active?' · Active':''}</strong>${esc(item.filename)}${item.instructions?`<small>${esc(item.instructions)}</small>`:''}</span><span style="display:flex;gap:6px;flex-wrap:wrap">${item.active?'<button class="btn" onclick="setResumeTemplate(null)">Use Neural Ant default</button>':`<button class="btn" onclick="setResumeTemplate(${Number(item.id)})">Activate</button>`}<button class="btn" onclick="removeResumeTemplate(${Number(item.id)})">Remove</button></span></div>`).join(''):'<div class="empty">No custom templates registered. Neural Ant default is active.</div>'}catch(e){if($('templateList'))$('templateList').textContent=e.message}}
async function registerTemplate(){const name=$('templateName').value.trim();const file=$('templateFile').files[0];if(!name||!file){toast('Enter a template name and choose a .docx file');return}try{const form=new FormData();form.append('name',name);form.append('instructions',$('templateInstructions').value.trim());form.append('file',file);await api('/templates',{method:'POST',body:form});$('templateName').value='';$('templateInstructions').value='';$('templateFile').value='';await loadTemplates();toast('Word template registered privately. Activate it to use its page setup and styles.')}catch(e){toast(e.message)}}
async function setResumeTemplate(id){try{const rows=await api('/templates');if(id===null){for(const item of rows.filter(item=>item.active))await api(`/templates/${item.id}`,{method:'PATCH',body:JSON.stringify({active:false})})}else await api(`/templates/${id}`,{method:'PATCH',body:JSON.stringify({active:true})});await loadTemplates();toast(id===null?'Neural Ant default resume style is active':'Custom resume template activated')}catch(e){toast(e.message)}}
async function removeResumeTemplate(id){if(!confirm('Remove this private Word template?'))return;try{await api(`/templates/${id}`,{method:'DELETE'});await loadTemplates();toast('Template removed')}catch(e){toast(e.message)}}
async function previewEmailUpdate(){
 const subject=$('emailSubject').value.trim();
 const body=$('emailBody').value.trim();
 const box=$('emailProposal');
 if(!subject||!body){toast('Add an email subject and message text');return}
 box.classList.remove('hidden');box.textContent='Reviewing the pasted message…';emailProposalForApproval=null;
 try{
  const result=await api('/sync/email/preview',{method:'POST',body:JSON.stringify({sender:$('emailSender').value.trim(),subject,received_at:$('emailReceived').value,body})});
  if(result.status==='proposal'){
   emailProposalForApproval=result;const p=result.proposed;const app=result.application;
   const currentOutcome=app.current_outcome?` / ${esc(app.current_outcome)}`:'';
   const proposedOutcome=p.outcome?` / ${esc(p.outcome)}`:'';
   const received=result.received_at?` · ${esc(result.received_at)}`:'';
   box.innerHTML=`<b>${esc(result.signal)} · ${esc(app.company)} — ${esc(app.title)}</b><p>Current: ${esc(app.current_stage)}${currentOutcome}</p><p>Proposed: ${esc(p.stage)}${proposedOutcome}</p><p>Subject: ${esc(result.subject)}${received}</p><p>${esc(result.message)}</p><button class="btn primary" onclick="approveEmailProposal()">Review and record this update</button>`;
  }else if(result.status==='ambiguous'){
   box.innerHTML=`<b>Needs manual matching</b><p>More than one tracked role matches this message. Select the right role in Applications and record it there.</p>${(result.candidates||[]).map(x=>`<div>${esc(x.company)} — ${esc(x.title)} (${esc(x.stage)})</div>`).join('')}`;
  }else{box.innerHTML=`<b>${esc(String(result.status||'No proposal').replaceAll('_',' '))}</b><p>${esc(result.message||'No update proposal was created.')}</p>`}
 }catch(e){box.textContent=e.message}
}
async function approveEmailProposal(){if(!emailProposalForApproval)return;const item=emailProposalForApproval;try{await api(`/applications/${item.application.id}`,{method:'PATCH',body:JSON.stringify(item.proposed)});emailProposalForApproval=null;$('emailProposal').innerHTML='<b>Tracker updated after your review.</b>';await loadApplications();toast('Application status updated from your reviewed email proposal')}catch(e){toast(e.message)}}
async function downloadPipelineCsv(){try{const response=await fetch('/api/reports/pipeline.csv',{credentials:'same-origin'});if(!response.ok){let detail='Pipeline export failed';try{detail=(await response.json()).detail||detail}catch{}throw Error(detail)}const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='neural-ant-notion-pipeline.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Downloaded a Notion-ready pipeline CSV.')}catch(e){toast(e.message)}}
async function resetWorkspace(){const scope=$('resetScope').value;const phrase=`RESET ${scope.toUpperCase()}`;if(!confirm(`This permanently deletes ${scope} data from this local Neural Ant workspace. Continue?`))return;const typed=prompt(`Type ${phrase} to confirm:`);if(typed!==phrase){toast('Reset cancelled. Confirmation did not match.');return}try{await api('/workspace/reset',{method:'POST',body:JSON.stringify({scope,confirmation:typed})});await Promise.all([loadProfile(),loadJobs(),loadApplications(),loadSources()]);await loadWorkspaceTools();toast(`${scope[0].toUpperCase()+scope.slice(1)} data deleted`)}catch(e){toast(e.message)}}

let activeWorkflowCommand='/help';
const workflowCommandAliases={'/search':'/scrape','/track':'/outcome','/draft':'/apply'};
const workflowCommandMap={
 '/help':{page:'overview',title:'Command guide',message:'Start with /setup: upload your resume and verify the extracted fields, then click Find & prepare jobs. That saves your profile, runs /scrape and /rank, and prepares local drafts for up to five top-fit remote roles with explicit sponsorship wording. Review the files and apply manually; use /interview and /outcome afterward.',action:'Show the command guide',focus:'#allCommands'},
 '/setup':{page:'profile',title:'Start here · Verify once, then run one click',message:'Upload your PDF or DOCX resume and review the extracted fields. Then choose Find & prepare jobs. Neural Ant saves your profile, refreshes configured boards, searches the remote index, scores the results, and prepares local drafts for up to five top-fit remote roles with explicit sponsorship wording. Your resume and work-authorization details stay local.',action:'Open profile setup',focus:'#resumeFile'},
 '/scrape':{page:'agents',title:'Rerun a job search',message:'Set role keywords, country, remote mode, and posting age, then start the broad index search or refresh the public boards. Only the search query and filters go to the broad index; your resume and work-authorization details stay local.',action:'Open job search',focus:'#freehireQuery'},
 '/rank':{page:'agents',title:'Review fit and sponsorship',message:'Use the fit score, matching skills, posting age, and sponsorship evidence to review roles. Confirm H‑1B support for this specific position with the employer; transfer wording or old filing history does not establish a new petition. C2C is a separate employment type.',action:'Open ranking filters',focus:'#sponsorFilter'},
 '/apply':{page:'agents',title:'Step 2 · Prepare a role-specific pack',message:'Choose a listing and select Prepare for review. Neural Ant saves a tailored resume, cover letter, and review notes for that role. Review the facts and downloaded files yourself, then complete the employer portal and submit manually.',action:'Open matching roles',focus:'#cloudJobs'},
 '/interview':{page:'tracker',title:'Step 3 · Prepare for an interview',message:'Open a tracked role and build its stage-specific interview pack. It uses saved resume examples, job requirements, tracker notes, and prepared drafts. Review the employer and posting yourself for current company details.',action:'Open tracked roles',focus:'#tracker'},
 '/outcome':{page:'tracker',title:'Step 4 · Track the outcome',message:'Update the role stage, notes, outcome, and follow-up date in Applications. You can review stale roles, save follow-up drafts, and archive a role after you choose. Neural Ant does not send messages or mark drafts as submitted.',action:'Open applications',focus:'#tracker'},
 '/match':{page:'matcher',title:'Check a role against your profile',message:'Paste the job description and, if available, its official HTTPS link. Neural Ant shows fit evidence, skill overlap, and sponsorship wording before you decide whether to track it.',action:'Open fit check',focus:'#jobTitle'},
 '/gmail-sync':{page:'tools',title:'Review an email update',message:'Paste a recruiter email you choose into the Gmail message tool. Neural Ant proposes a tracker update for review; the email body is not saved, and no Gmail account is connected.',action:'Open email review',focus:'#emailSubject'},
 '/html-report':{page:'tracker',title:'Export the pipeline report',message:'Use the offline report button in Applications to download a local HTML snapshot of the tracker. It excludes resume and profile contact details.',action:'Open report export',focus:'#tracker button[onclick="downloadApplicationReport()"]'},
 '/notion-sync':{page:'tools',title:'Export for Notion',message:'Download the Notion-ready CSV from Tools, then import it manually. This is a one-way export, not a live Notion connection.',action:'Open CSV export',focus:'#tools button[onclick="downloadPipelineCsv()"]'},
 '/expand':{page:'tools',title:'Review profile skill evidence',message:'Paste copied text from a public portfolio, GitHub profile, or course syllabus. Neural Ant shows source-cited skill suggestions; approve each suggestion before it changes your profile.',action:'Open skill evidence',focus:'#expandLabel'},
 '/upskill':{page:'copilot',title:'Create a skill-gap learning plan',message:'Choose or paste a target job context. The plan points out skills missing from the saved skill list; it does not claim you lack experience with them.',action:'Open learning plan',focus:'#copilotContext',taskType:'upskill'},
 '/add-template':{page:'tools',title:'Register a Word template',message:'Upload a DOCX template to preserve its page setup and selected styles in generated resume drafts. The uploaded template stays in the private local workspace.',action:'Open template setup',focus:'#templateName'},
 '/add-portal':{page:'agents',title:'Configure a public job source',message:'Choose a supported public ATS or API adapter, enter its board identifier or query, add the source, then refresh search. Neural Ant reads public listings and does not scrape LinkedIn.',action:'Open source setup',focus:'#sourceType'},
 '/reset':{page:'tools',title:'Reset workspace data',message:'Choose a reset scope and read the confirmation prompt carefully. This command only opens the reset controls; nothing is deleted until you confirm the scope and type its confirmation phrase.',action:'Open reset settings',focus:'#resetScope'},
 '/tools':{page:'tools',title:'Additional workflow tools',message:'Use this area for public-profile skill evidence, Word templates, email-status review, exports, and scoped workspace reset.',action:'Open workflow tools',focus:'#tools'}
};
function appendChatMessage(role,text,title,command,action){
 const thread=$('chatThread');if(!thread)return;
 const row=document.createElement('div');row.className=`chat-message ${role}`;
 if(role==='assistant'){const avatar=document.createElement('div');avatar.className='chat-avatar';avatar.textContent='NA';row.appendChild(avatar)}
 const bubble=document.createElement('div');bubble.className='chat-bubble';
 if(title){const heading=document.createElement('strong');heading.textContent=title;bubble.appendChild(heading)}
 const paragraph=document.createElement('p');paragraph.textContent=text;bubble.appendChild(paragraph);
 if(command&&action){const button=document.createElement('button');button.type='button';button.className='btn lite';button.textContent=action;button.addEventListener('click',()=>openWorkflowCommand(command));bubble.appendChild(button)}
 row.appendChild(bubble);thread.appendChild(row);thread.scrollTop=thread.scrollHeight;
}
function openWorkflowCommand(command){
 const item=workflowCommandMap[command];if(!item)return;
 activeWorkflowCommand=command;
 if(item.taskType&&$('taskType')){$('taskType').value=item.taskType;updateCopilotFields()}
 showPage(item.page);
 document.querySelectorAll('.nav button').forEach(button=>button.classList.toggle('active',button.dataset.command===command));
 if(item.focus){requestAnimationFrame(()=>{const target=document.querySelector(item.focus);target?.scrollIntoView({behavior:'smooth',block:'center'});if(target&&target.matches('input,textarea,select'))target.focus({preventScroll:true})})}
}
function runWorkflowCommand(raw,openImmediately=false){
 const text=String(raw||'').trim();if(!text)return;
 const requested=text.split(/\s+/)[0].toLowerCase();const command=workflowCommandAliases[requested]||requested;const item=workflowCommandMap[command];
 appendChatMessage('user',text);
 if(!item){appendChatMessage('assistant','I don’t recognize that command. Use /help or choose a command from the list.', 'Available commands',null,null);const drawer=$('allCommands');if(drawer)drawer.open=true;return}
 if(command==='/scrape'){
  const terms=text.split(/\s+/).slice(1).join(' ');
  if(terms&&$('freehireQuery')){$('freehireQuery').value=terms;$('freehireQuery').dataset.userEdited='true'}
 }
 if(command==='/help'){$('allCommands').open=true}
 appendChatMessage('assistant',item.message,item.title,command,item.action);
 if(openImmediately)openWorkflowCommand(command);
}
function submitWorkflowCommand(event){event.preventDefault();const input=$('commandInput');const value=input?.value||'';if(input)input.value='';runWorkflowCommand(value,false)}
document.addEventListener('click',event=>{const button=event.target.closest('[data-command]');if(!button)return;if(button.classList.contains('nav-command')){openWorkflowCommand(button.dataset.command);return}runWorkflowCommand(button.dataset.command,false)});
$('homeResumeFile')?.addEventListener('change',()=>uploadResume('homeResumeFile'));
checkSession();
